{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table andamen_db.maplemonk.po_allocation_gross_sales as WITH grn_running_total AS ( SELECT po_id, sku, units_bought, first_grn_date, SUM(units_bought) OVER (PARTITION BY sku ORDER BY first_grn_date ASC ROWS UNBOUNDED PRECEDING) AS running_grn_quantity FROM ( select po_id, A.value:sku::string sku, min(grn_created_at::date) first_grn_Date, sum(ifnull(A.value:original_quantity::float,0)) units_bought, from andamen_db.maplemonk.andamen_ee_grn_details, lateral flatten(input => grn_items) A group by 1,2 ) ), gross_sales_running_total AS ( SELECT sku, gross_quantity, ordeR_Date, SUM(gross_quantity) OVER (PARTITION BY sku ORDER BY ordeR_date ASC ROWS UNBOUNDED PRECEDING) AS running_sales_quantity FROM ( select sku, order_Date::date ordeR_Date, sum(quantity) gross_quantity, from andamen_db.maplemonk.andamen_db_sales_consolidated group by 1,2 ) ), fifo_allocation AS ( SELECT g.po_id, g.sku, LEAST( g.running_grn_quantity - COALESCE(LAG(g.running_grn_quantity) OVER (PARTITION BY g.sku ORDER BY g.firsT_grn_date ASC), 0), s.running_sales_quantity - COALESCE(LAG(s.running_sales_quantity) OVER (PARTITION BY s.sku ORDER BY s.order_Date ASC), 0) ) AS allocated_quantity FROM gross_sales_running_total s JOIN grn_running_total g ON s.sku = g.sku AND s.running_sales_quantity <= g.running_grn_quantity ) SELECT po_id, sku, SUM(allocated_quantity) AS allocated_quantity FROM fifo_allocation GROUP BY po_id, sku ORDER BY sku, po_id; create or replace table andamen_db.maplemonk.po_allocation_net_sales as WITH grn_running_total AS ( SELECT po_id, sku, units_bought, first_grn_date, SUM(units_bought) OVER (PARTITION BY sku ORDER BY first_grn_date ASC ROWS UNBOUNDED PRECEDING) AS running_grn_quantity FROM ( select po_id, A.value:sku::string sku, min(grn_created_at::date) first_grn_Date, sum(ifnull(A.value:original_quantity::float,0)) units_bought, from andamen_db.maplemonk.andamen_ee_grn_details, lateral flatten(input => grn_items) A group by 1,2 ) ), gross_sales_running_total AS ( SELECT sku, net_quantity, ordeR_Date, SUM(net_quantity) OVER (PARTITION BY sku ORDER BY ordeR_date ASC ROWS UNBOUNDED PRECEDING) AS running_sales_quantity FROM ( select sku, order_Date::date ordeR_Date, sum(quantity) net_quantity, from andamen_db.maplemonk.andamen_db_sales_consolidated where order_status not in (\'CANCELLED\',\'SHIPPED - RETURNED TO SELLER\',\'SHIPPED - LOST IN TRANSIT\',\'RETURNED\',\'SHIPPED - RETURNING TO SELLER\') and shipping_status not in (\'RTO DELIVERED\',\'RTO IN TRANSIT\',\'CANCELED\',\'LOST\',\'SHIPMENT LOST\',\'DELIVERED TO ORIGIN\',\'RETURNED\',\'RTO INITIATED\',\'RTO NDR\',\'DISPOSED OFF\') group by 1,2 ) ), fifo_allocation AS ( SELECT g.po_id, g.sku, LEAST( g.running_grn_quantity - COALESCE(LAG(g.running_grn_quantity) OVER (PARTITION BY g.sku ORDER BY g.firsT_grn_date ASC), 0), s.running_sales_quantity - COALESCE(LAG(s.running_sales_quantity) OVER (PARTITION BY s.sku ORDER BY s.order_Date ASC), 0) ) AS allocated_quantity FROM gross_sales_running_total s JOIN grn_running_total g ON s.sku = g.sku AND s.running_sales_quantity <= g.running_grn_quantity ) SELECT po_id, sku, SUM(allocated_quantity) AS allocated_quantity FROM fifo_allocation GROUP BY po_id, sku ORDER BY sku, po_id; create or replace table andamen_db.maplemonk.andamen_db_exit_margin_report as select a.po_id, a.sku, first_grn_Date, units_bought, price cogp, mrp, div0(mrp, price) buying_multiple, 0.05 as assumed_discount, div0(price, (mrp*(1-0.05)/1.12)) assumed_cogs, units_bought*mrp gross_mrp_value, units_bought*price total_cogp, grosssales.discount_percent actual_discount, div0(mrp*(1-grosssales.discount_percent),1.12) arv, pan.net_quantity nrv_Sale_units, div0(mrp*(1-grosssales.discount_percent),1.12) * pan.net_quantity nrv_Sale_value, div0(price,div0(mrp*(1-grosssales.discount_percent),1.12)) actual_cogs_percent, div0(pan.net_quantity, units_bought) st, pag.gross_quantity gob_units, div0(pag.gross_quantity - pan.net_quantity,pag.gross_quantity) leakages_percent, pag.gross_quantity - pan.net_quantity leakage_units, (pag.gross_quantity - pan.net_quantity)*500 leakages_cost, div0(mrp*(1-grosssales.discount_percent),1.12) * pan.net_quantity - units_bought*price - (pag.gross_quantity - pan.net_quantity)*500 exit_margin, div0(div0(mrp*(1-grosssales.discount_percent),1.12) * pan.net_quantity - units_bought*price - (pag.gross_quantity - pan.net_quantity)*500 , units_bought*mrp) exit_margin_percent, div0(units_bought*price + (pag.gross_quantity - pan.net_quantity)*500, div0(mrp*(1-grosssales.discount_percent),1.12)) units_to_breakeven, pm.live_Date from (select po_id, A.value:sku::string sku, min(grn_created_at::date) first_grn_Date, sum(ifnull(A.value:original_quantity::float,0)) units_bought, div0(sum(A.value:grn_detail_price::float),sum(ifnull(A.value:original_quantity::float,0))) price from andamen_db.maplemonk.andamen_ee_grn_details, lateral flatten(input => grn_items) A group by 1,2 ) a left join (select sku, mrp, live_Date from ( select sku, mrp, created_at::Date live_Date, row_number() over (partition by sku order by 1) rw from andamen_db.maplemonk.easyecom_easyecom_andamen_product_master )where rw = 1 ) pm on a.sku = pm.sku left join ( select sku, sum(quantity) net_quantity from andamen_db.maplemonk.andamen_db_sales_consolidated where order_status not in (\'CANCELLED\',\'SHIPPED - RETURNED TO SELLER\',\'SHIPPED - LOST IN TRANSIT\',\'RETURNED\',\'SHIPPED - RETURNING TO SELLER\') and shipping_status not in (\'RTO DELIVERED\',\'RTO IN TRANSIT\',\'CANCELED\',\'LOST\',\'SHIPMENT LOST\',\'DELIVERED TO ORIGIN\',\'RETURNED\',\'RTO INITIATED\',\'RTO NDR\',\'DISPOSED OFF\') group by 1 ) netsales on a.sku = netsales.sku left join ( select sku,div0(sum(discount), sum(ifnull(selling_price,0) + ifnull(discount,0))) discount_percent from andamen_db.maplemonk.andamen_db_sales_consolidated group by 1 ) grosssales on a.sku = grosssales.sku left join (select po_id, sku, allocated_quantity gross_quantity from andamen_db.maplemonk.po_allocation_gross_sales) pag on pag.sku = a.sku and pag.po_id = a.po_id left join (select po_id, sku, allocated_quantity net_quantity from andamen_db.maplemonk.po_allocation_net_sales) pan on pan.sku = a.sku and pan.po_id = a.po_id ;",
                    "transaction": true
                }
            ) }}
